int hvbms_hv_pack(
    uint8_t *dst_p,
    const struct hvbms_hv_t *src_p,
    size_t size)
{
    uint16_t hv_channel1_act;
    uint16_t hv_channel2_act;
    uint16_t hv_channel3_act;

    if (size < 8u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 8);

    hv_channel1_act = (uint16_t)src_p->hv_channel1_act;
    dst_p[0] |= pack_left_shift_u16(hv_channel1_act, 0u, 0xffu);
    dst_p[1] |= pack_right_shift_u16(hv_channel1_act, 8u, 0xffu);
    hv_channel2_act = (uint16_t)src_p->hv_channel2_act;
    dst_p[2] |= pack_left_shift_u16(hv_channel2_act, 0u, 0xffu);
    dst_p[3] |= pack_right_shift_u16(hv_channel2_act, 8u, 0xffu);
    hv_channel3_act = (uint16_t)src_p->hv_channel3_act;
    dst_p[4] |= pack_left_shift_u16(hv_channel3_act, 0u, 0xffu);
    dst_p[5] |= pack_right_shift_u16(hv_channel3_act, 8u, 0xffu);

    return (8);
}

