int hvbms_bmu3_int_temperature_pack(
    uint8_t *dst_p,
    const struct hvbms_bmu3_int_temperature_t *src_p,
    size_t size)
{
    if (size < 8u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 8);

    dst_p[0] |= pack_left_shift_u8(src_p->temp_pcb1, 0u, 0xffu);
    dst_p[1] |= pack_left_shift_u8(src_p->temp_pcb2, 0u, 0xffu);
    dst_p[2] |= pack_left_shift_u8(src_p->temp_1, 0u, 0xffu);
    dst_p[3] |= pack_left_shift_u8(src_p->temp_2, 0u, 0xffu);
    dst_p[4] |= pack_left_shift_u8(src_p->temp_3, 0u, 0xffu);
    dst_p[5] |= pack_left_shift_u8(src_p->temp_4, 0u, 0xffu);
    dst_p[6] |= pack_left_shift_u16(src_p->balancing_bitmask, 0u, 0xffu);
    dst_p[7] |= pack_right_shift_u16(src_p->balancing_bitmask, 8u, 0xffu);

    return (8);
}

int hvbms_bmu3_int_temperature_unpack(
    struct hvbms_bmu3_int_temperature_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    if (size < 8u) {
        return (-EINVAL);
    }

    dst_p->temp_pcb1 = unpack_right_shift_u8(src_p[0], 0u, 0xffu);
    dst_p->temp_pcb2 = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
    dst_p->temp_1 = unpack_right_shift_u8(src_p[2], 0u, 0xffu);
    dst_p->temp_2 = unpack_right_shift_u8(src_p[3], 0u, 0xffu);
    dst_p->temp_3 = unpack_right_shift_u8(src_p[4], 0u, 0xffu);
    dst_p->temp_4 = unpack_right_shift_u8(src_p[5], 0u, 0xffu);
    dst_p->balancing_bitmask = unpack_right_shift_u16(src_p[6], 0u, 0xffu);
    dst_p->balancing_bitmask |= unpack_left_shift_u16(src_p[7], 8u, 0xffu);

    return (0);
}

